SourceCode.Declaration:
/// <summary>
/// Data contract class for managing bulk workflow work items.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
[DataContractAttribute]
class METBulkWFWorkItemManagerMainContract
{
    WorkflowComment             workflowComment;
    int                         noOfThreads;
    WorkflowWorkItemActionType  actionType;
    str                         packedQuery;
    UserId                      userId;

}

Method.Source:
/// <summary>
/// Gets or sets the number of threads.
/// </summary>
/// <param name="_noOfThreads">The number of threads.</param>
/// <returns>The number of threads.</returns>
[DataMember]
public int parmNoOfThreads(int _noOfThreads = noOfThreads)
{
    noOfThreads = _noOfThreads;

    return noOfThreads;
}

/// <summary>
/// Gets or sets the workflow action type.
/// </summary>
/// <param name="_actionType">The workflow action type.</param>
/// <returns>The workflow action type.</returns>
[DataMember]
public WorkflowWorkItemActionType parmWorkflowActionType(WorkflowWorkItemActionType _actionType = actionType)
{
    actionType = _actionType;

    return actionType;
}

/// <summary>
/// Gets or sets the packed query.
/// </summary>
/// <param name="_packedQuery">The packed query string.</param>
/// <returns>The packed query string.</returns>
[DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', querystr(METBulkWFFreeTextInvoiceManager))]
public str parmQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

/// <summary>
/// Gets or sets the workflow comment.
/// </summary>
/// <param name="_workflowComment">The workflow comment.</param>
/// <returns>The workflow comment.</returns>
[DataMember]
public WorkflowComment parmWorkFlowComment(WorkflowComment _workflowComment = workflowComment)
{
    workflowComment = _workflowComment;

    return workflowComment;
}

/// <summary>
/// Gets or sets the userid.
/// </summary>
/// <param name="_userId">The userid to get reassigned.</param>
/// <returns>The userid comment.</returns>
[DataMember]
public UserId parmUserId(UserId _userId = userId)
{
    userId = _userId;

    return userId;
}

/// <summary>
/// Gets the query object from the packed query string.
/// </summary>
/// <returns>The query object.</returns>
internal Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Sets the query object and packs it into a string.
/// </summary>
/// <param name="_query">The query object.</param>
internal void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}
